async function renderUsers(){if(role!=='owner')throw Error('إدارة المستخدمين متاحة لمدير الجهة');const rows=await result(db.from('client_admins').select('*').order('email'));$('#content').innerHTML='<p class="muted">تحدد هذه القائمة صلاحية الحساب. تفعيل الحسابات الجديدة وتجهيز دخولها يتم من مسؤول النظام؛ إضافة البريد وحدها لا ترسل دعوة.</p>'+list('المستخدمون المصرح لهم',rows,r=>`<b dir="ltr">${h(r.email)}</b><p>${h(label(r.role))} · ${r.active?'نشط':'موقوف'}</p>`,false);const editor=r=>edit('صلاحية مستخدم',field('email','البريد الإلكتروني',r.email,'email',true)+select('role','الدور',r.role||'editor',roleNames)+`<label class="check-label"><input type="checkbox" name="active" ${r.active!==false?'checked':''}>نشط</label>`,async f=>{const email=String(f.get('email')).trim().toLowerCase();if(r.email&&email!==r.email)throw Error('أضف البريد الجديد مستقلاً ثم أوقف القديم');await result(db.from('client_admins').upsert({email,role:String(f.get('role')),active:f.has('active')},{onConflict:'email'}))});$('#add').onclick=()=>editor({});actions(rows,editor,()=>{})}
function downloadData(name,content,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function bindWorkspaceTools(){const entries=[...$('#content').querySelectorAll('.list-row')];if(!['sections','records','documents','users'].includes(tab)||!workspaceRows.length)return;const rows=[...workspaceRows],state=r=>typeof r.published==='boolean'?(r.published?'published':'draft'):r.state??(r.status?r.status+(r.is_public?':public':':private'):r.active===true?'active':r.active===false?'inactive':''),states=[...new Set(rows.map(state))],names={draft:'مسودة',published:'منشور','draft:private':'ملف خاص — مسودة','approved:public':'ملف معتمد وعام','approved:private':'ملف معتمد وخاص',active:'نشط',inactive:'موقوف'};const tools=document.createElement('section');tools.className='workspace-tools';tools.innerHTML='<div class="toolbar"><label>بحث في السجلات<input id="workspace-search" type="search" placeholder="اسم، عنوان، تصنيف أو قيمة…"></label>'+select('workspace-status','حالة السجل','',{'':'جميع الحالات',...Object.fromEntries(states.map(s=>[s,Object.hasOwn(names,s)?names[s]:String(s)]))})+'<button class="ghost" id="export-csv">تصدير النتائج CSV</button><button class="ghost" id="export-json">تنزيل البيانات JSON</button></div><p id="workspace-count" class="muted" role="status"></p>';$('#content').querySelector('.workspace-heading').after(tools);let visible=rows;function filter(){const term=tools.querySelector('input').value.trim().normalize('NFKC').toLocaleLowerCase('ar'),selected=tools.querySelector('select').value;visible=[];entries.forEach((node,i)=>{const text=(JSON.stringify(rows[i])+' '+node.textContent).normalize('NFKC').toLocaleLowerCase('ar'),show=(!term||text.includes(term))&&(!selected||state(rows[i])===selected);node.classList.toggle('workspace-filtered',!show);if(show)visible.push(rows[i])});tools.querySelector('#workspace-count').textContent=`عرض ${visible.length} من ${rows.length} سجل`;tools.querySelectorAll('button').forEach(b=>b.disabled=!visible.length)}tools.querySelector('input').oninput=filter;tools.querySelector('select').onchange=filter;tools.querySelector('#export-json').onclick=()=>downloadData('سجلات-الجهة.json',JSON.stringify(visible,null,2),'application/json;charset=utf-8');tools.querySelector('#export-csv').onclick=()=>{const flat=visible.map(r=>Object.fromEntries(Object.entries(r).flatMap(([k,v])=>k==='payload'&&v&&typeof v==='object'?Object.entries(v).map(([key,value])=>['payload.'+key,value]):[[k,v]]))),keys=[...new Set(flat.flatMap(Object.keys))],cell=v=>{let text=v==null?'':typeof v==='object'?JSON.stringify(v):String(v);if(typeof v!=='number'&&/^[\s]*[=+@-]/.test(text))text="'"+text;return '"'+text.replace(/"/g,'""')+'"'};downloadData('سجلات-الجهة.csv','\uFEFF'+[keys,...flat.map(r=>keys.map(k=>r[k]))].map(row=>row.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8')};filter()}
async function renderOverview(){const forRole=role;const specs=role==='volunteer_manager'?[['المتطوعون','client_records',q=>q.eq('kind','volunteer')],['طلبات المشاركة','client_records',q=>q.eq('kind','application')],['سجلات الساعات','client_records',q=>q.eq('kind','hours')]]:[['الأقسام المنشورة','site_sections',q=>q.eq('published',true)],['مسودات المحتوى المتاحة لك','client_records',q=>q.eq('state','draft')],['ملفات تنتظر الاعتماد','client_documents',q=>q.eq('status','draft')]];let box=$('#daily-overview');if(!box){box=document.createElement('section');box.id='daily-overview';box.setAttribute('aria-label','مؤشرات الإدارة');$('#admin-body').prepend(box)}const results=await Promise.all(specs.map(async([title,table,configure])=>{try{const r=await configure(db.from(table).select('id',{count:'exact',head:true}));return{title,value:r.error||r.count==null?null:r.count}}catch{return{title,value:null}}}));if(role!==forRole||!box.isConnected)return;box.innerHTML='<div class="toolbar">'+results.map(r=>'<article class="card">'+uiIcon('overview')+'<p class="muted">'+h(r.title)+'</p><strong>'+h(r.value==null?'تعذر تحميل المؤشر':r.value)+'</strong></article>').join('')+'</div><p class="muted">مؤشرات فعلية للسجلات التي تسمح صلاحيتك بقراءتها.</p>'}
function setupAdminLayout(){if($('#admin-workspace'))return;const dashboard=$('#dashboard'),tabs=$('#tabs'),workspace=document.createElement('div'),sidebar=document.createElement('aside'),main=document.createElement('main');workspace.id='admin-workspace';sidebar.id='admin-sidebar';main.id='admin-body';sidebar.innerHTML='<p class="sidebar-caption">مساحة عمل الجهة</p>';for(const button of tabs.querySelectorAll('button'))button.insertAdjacentHTML('afterbegin',uiIcon(button.dataset.tab));sidebar.append(tabs);if(/^https:\/\//.test(cfg.publicUrl||'')){const a=document.createElement('a');a.href=cfg.publicUrl;a.target='_blank';a.rel='noopener noreferrer';a.className='public-site-link';a.textContent='فتح الموقع العام ↗';sidebar.append(a)}const refs=document.createElement('details');refs.className='official-references';refs.innerHTML='<summary>مراجع التجهيز</summary><a href="https://ncnp.gov.sa/ar/services/الإفصاح" target="_blank" rel="noopener noreferrer">خدمة الإفصاح — المركز الوطني</a><a href="https://ncnp.gov.sa/ar/regulations" target="_blank" rel="noopener noreferrer">الأنظمة واللوائح الرسمية</a><a href="https://nvg.gov.sa/" target="_blank" rel="noopener noreferrer">المنصة الوطنية للعمل التطوعي</a><p>للاسترشاد وتجهيز الوثائق، وليست شهادة امتثال أو ربطًا حكوميًا.</p>';sidebar.append(refs);main.append($('#content'));workspace.append(sidebar,main);dashboard.append(workspace)}
async function renderTab(){setupAdminLayout();let refButton=$('[data-tab=reference]');if(!refButton){refButton=document.createElement('button');refButton.dataset.tab='reference';refButton.textContent='تحرير الواجهة المرجعية';$('#tabs').append(refButton);refButton.onclick=()=>{if(!closeModal())return;tab='reference';void renderTab()}}refButton.hidden=role!=='owner';try{sectionCatalog=await result(db.from('site_sections').select('*').order('position'));if(role!=='volunteer_manager'){let nav=$('#section-shortcuts');if(!nav){nav=document.createElement('nav');nav.id='section-shortcuts';nav.className='toolbar';nav.setAttribute('aria-label','تحرير الأقسام مباشرة');$('#content').before(nav)}nav.innerHTML='<label>الوصول السريع إلى قسم<input id="section-shortcut-search" type="search" placeholder="ابحث عن البرامج أو المجلس أو أي قسم…"></label><div id="section-shortcut-buttons">'+sectionCatalog.map(s=>`<div class="toolbar shortcut-row" data-search-title="${h(s.title)}"><button class="ghost" data-open-section="${h(s.id)}">تحرير ${h(s.title)}</button>${sectionRecordKind(s)?`<button class="ghost" data-section-records="${h(s.id)}">عناصر ${h(s.title)}</button>`:''}</div>`).join('')+'</div>';nav.querySelector('#section-shortcut-search').oninput=e=>{const term=e.target.value.trim().toLocaleLowerCase('ar');nav.querySelectorAll('[data-search-title]').forEach(row=>row.hidden=!row.dataset.searchTitle.toLocaleLowerCase('ar').includes(term))};nav.querySelectorAll('[data-open-section]').forEach(b=>b.onclick=async()=>{if(!closeModal())return;tab='sections';await renderTab();openSectionEditor?.(sectionCatalog.find(s=>s.id===b.dataset.openSection))});nav.querySelectorAll('[data-section-records]').forEach(b=>b.onclick=()=>{if(!closeModal())return;recordSectionId=b.dataset.sectionRecords;recordKind=sectionRecordKind(sectionCatalog.find(s=>s.id===recordSectionId));tab='records';void renderTab()})}else $('#section-shortcuts')?.remove();$('#content').innerHTML='<p class="muted">جارٍ التحميل…</p>';document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));if(role!=='volunteer_manager')await reloadMedia();await({reference:renderReference,sections:renderSections,records:renderRecords,documents:renderDocuments,users:renderUsers,settings:renderSettings}[tab])();bindWorkspaceTools();await renderOverview();}catch(e){$('#content').innerHTML='<p class="notice error">تعذر تحميل البيانات. تحقق من الربط والصلاحية.</p><button id="retry">إعادة المحاولة</button>';$('#retry').onclick=renderTab;message(e.message,true)}}
let recovery=location.hash.includes('type=recovery');
async function load(){if(!cfg.supabaseUrl||!cfg.publishableKey){$('#setup').hidden=false;return}try{db??=window.MizallaDB.createClient(cfg.supabaseUrl,cfg.publishableKey);const{data,error}=await db.auth.getSession();if(error)throw error;$('#login').hidden=!!data.session;$('#dashboard').hidden=!data.session;$('#logout').hidden=!data.session;$('#password-setup').hidden=true;if(!data.session)return;role=await result(db.rpc('client_role'));if(!role){await db.auth.signOut();$('#login').hidden=false;$('#dashboard').hidden=true;$('#logout').hidden=true;throw Error('الحساب غير مصرح له بإدارة هذه الجهة')}if(recovery||data.session.user.user_metadata?.needs_password_setup){$('#dashboard').hidden=true;$('#password-setup').hidden=false;return}$('#role').textContent=roleNames[role]||role;for(const name of['users','settings']){const node=document.querySelector('[data-tab='+name+']');if(node)node.hidden=role!=='owner'}for(const name of['sections','documents'])document.querySelector('[data-tab='+name+']').hidden=role==='volunteer_manager';if(role==='volunteer_manager')tab='records';await renderTab();const identity=await result(db.from('site_settings').select('data').eq('id',1).single());let org=identity.data.organization||{};if(role==='owner'&&!org.appIcon192&&cfg.publicUrl&&cfg.adminUrl){try{const logo=String(org.logoUrl||''),doc=logo.startsWith('media://')?media.find(m=>m.id===logo.slice(8)):null;if(logo.startsWith('media://')&&!(doc?.is_public&&doc.status==='approved'))throw Error('اعتمد شعار الجهة من إعدادات الهوية لتفعيل أيقونة التطبيق');const icons=await publishBranding(db,org,cfg,mediaURL),fresh=await result(db.from('site_settings').select('data').eq('id',1).single());if(['name','logoUrl','primary'].every(k=>fresh.data.organization?.[k]===org[k])){org={...fresh.data.organization,...icons};await result(db.from('site_settings').update({data:{...fresh.data,organization:org}}).eq('id',1))}}catch(e){message('تجهيز الأيقونة: '+e.message,true)}}await applyBranding(org,true)}catch(e){message('تعذر الدخول: '+e.message,true)}}
$('#password-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const password=$('#new-password').value;if(password.length<12||password!==$('#confirm-password').value)throw Error('استخدم ١٢ حرفًا على الأقل وتأكد من تطابق كلمتي المرور');const{error}=await db.auth.updateUser({password,data:{needs_password_setup:false}});if(error)throw error;$('#new-password').value='';$('#confirm-password').value='';recovery=false;message('حُفظت كلمة المرور');await load()}catch(e){message(e.message,true)}finally{button.disabled=false}};
$('#login-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const{error}=await db.auth.signInWithPassword({email:$('#email').value.trim(),password:$('#password').value});if(error)throw error;$('#password').value='';await load()}catch(e){message('تعذر تسجيل الدخول: '+e.message,true)}finally{button.disabled=false}};$('#logout').onclick=async()=>{if(!closeModal())return;$('#section-shortcuts')?.remove();$('#daily-overview')?.remove();await db.auth.signOut({scope:'local'});role=null;await load()};document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{if(!closeModal())return;tab=b.dataset.tab;if(tab==='records')recordSectionId='';void renderTab()});await load();if(db)db.auth.onAuthStateChange(()=>{setTimeout(()=>void load(),0)});
